type ClaimOAuthTokenRevocationsRow struct {
	Id string `json:"id"`
	ConnectionId string `json:"connection_id"`
	ProviderId string `json:"provider_id"`
	TokenCiphertext []byte `json:"token_ciphertext"`
	TokenKeyId string `json:"token_key_id"`
	ClaimToken *string `json:"claim_token"`
	Attempts int64 `json:"attempts"`
	AvailableAt time.Time `json:"available_at"`
	LeaseUntil *time.Time `json:"lease_until"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

func ClaimOAuthTokenRevocations(ctx context.Context, db DBTX, UpdatedAt time.Time, LeaseUntil time.Time, LimitVal int64) ([]ClaimOAuthTokenRevocationsRow, error) {
	rows, err := db.Query(ctx, "UPDATE provider_token_revocation_jobs SET status = 'processing', attempts = attempts + 1,   lease_until = $2::TIMESTAMPTZ, claim_token = gen_random_uuid(), updated_at = $1::TIMESTAMPTZ WHERE id IN (   SELECT id FROM provider_token_revocation_jobs   WHERE (status = 'pending' AND available_at <= $1::TIMESTAMPTZ)      OR (status = 'processing' AND lease_until <= $1::TIMESTAMPTZ)   ORDER BY available_at, id   LIMIT $3::INT8   FOR UPDATE SKIP LOCKED ) RETURNING id::STRING AS id, COALESCE(connection_id::STRING, '') AS connection_id,   provider_id, token_ciphertext, COALESCE(token_key_id, '') AS token_key_id,   claim_token::STRING AS claim_token, attempts, available_at,   lease_until, created_at, updated_at", UpdatedAt, LeaseUntil, LimitVal)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var result []ClaimOAuthTokenRevocationsRow
	for rows.Next() {
		var r ClaimOAuthTokenRevocationsRow
		if err := rows.Scan(&r.Id, &r.ConnectionId, &r.ProviderId, &r.TokenCiphertext, &r.TokenKeyId, &r.ClaimToken, &r.Attempts, &r.AvailableAt, &r.LeaseUntil, &r.CreatedAt, &r.UpdatedAt); err != nil {
			return nil, err
		}
		result = append(result, r)
	}
	return result, rows.Err()
}

func CompleteOAuthTokenRevocation(ctx context.Context, db DBTX, Id uuid.UUID, ClaimToken uuid.UUID) (int64, error) {
	result, err := db.Exec(ctx, "DELETE FROM provider_token_revocation_jobs WHERE id = $1::UUID AND status = 'processing' AND claim_token = $2::UUID", Id, ClaimToken)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

func RetryOAuthTokenRevocation(ctx context.Context, db DBTX, Id uuid.UUID, ClaimToken uuid.UUID, AvailableAt time.Time) (int64, error) {
	result, err := db.Exec(ctx, "UPDATE provider_token_revocation_jobs SET status = 'pending', available_at = $3::TIMESTAMPTZ,   lease_until = NULL, claim_token = NULL, updated_at = now() WHERE id = $1::UUID AND status = 'processing' AND claim_token = $2::UUID", Id, ClaimToken, AvailableAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

func DeadLetterOAuthTokenRevocation(ctx context.Context, db DBTX, Id uuid.UUID, ClaimToken uuid.UUID, AvailableAt time.Time) (int64, error) {
	result, err := db.Exec(ctx, "UPDATE provider_token_revocation_jobs SET status = 'dead', available_at = $3::TIMESTAMPTZ,   lease_until = NULL, claim_token = NULL,   terminal_at = $3::TIMESTAMPTZ, terminal_reason = 'max_attempts_exhausted',   updated_at = $3::TIMESTAMPTZ WHERE id = $1::UUID AND status = 'processing' AND claim_token = $2::UUID", Id, ClaimToken, AvailableAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
